// Struct represents a struct with its field names.
type Struct struct {
	Name    string // The name of the struct.
	FIELDS  []string // The list of field names.
}

func extractStructFields(srcFile *os.File) (struct.Fields, error) {
	var fields []string
	ast.Inspect(srcFile, func(n ast.Node) bool {
		if n, ok := n.(*ast.TypeSpec); ok {
			if s, ok := n.Type.(ast.StructType); ok {
				for _, f := range s.Fields.List {
					fields = append(fields, f.Names[0].Name)
				}
			}
		}
		return true
	})
	return fields, nil
}

func generateAvroSchema(structName string, srcFilePath string) error {
	file, err := os.Open(srcFilePath)
	if err != nil {
		return fmt.Errorf("failed to open file: %w", err)
	}
	defer file.Close()

	srcBytes, err := ioutil.ReadAll(file)
	if err != nil {
		return fmt.Errorf("error reading file: %w", err)
	}

	var structs []Struct
	err = parser.ParseFiles(&structs, token.NewFileSet(), string(srcBytes), nil)
	if err != nil {
		return fmt.Errorf("failed to parse file: %w", err)
	}

	structToGenerate := structsByName(structs, structName)

	if len(structToGenerate.FIELDS) == 0 {
		return fmt.Errorf("struct '%s' not found in the provided Go code.", structName)
	}

	fmt.Println(fmt.Sprintf("Generated Avro schema for struct %s:\n\n", structName))
	fmt.Println(`{
