 "type": "record",
 "name": "%s",
 "fields": [`, structName)
	for _, fieldName := range structToGenerate.FIELDS {
		fmt.Printf(`{"name": "%s", "type": "string"}, `, fieldName)
	}
	fmt.Println("]")
	return nil
}

func structsByName(structs []Struct, structName string) Struct {
	for _, s := range structs {
		if s.Name == structName {
