    <script>
        $(document).ready(function() {
            $('#displayBackground').click(function() {
                // Get the current background image URL from the user's machine
                var backgroundImage = window.getComputedStyle(document.body).backgroundImage;

                // If there is no background image set, return early
                if (!backgroundImage) {
                    alert('No background image found.');
                    return;
                }

                // Create a new window object with the body element
                var win = window.open('', '_blank', 'height=400,width=600');

                // Set the body element's style to match the background image
                win.document.body.style.backgroundImage = backgroundImage.replace(/url\((.*)\)/, 'url($1)');

                // Open the window
                win.focus();
            });
        });
    </script>

</body>
</html>
